// Code node "Parse request": turns an incoming email into one structured RFQ row.
// Runs once for all items. Reads the Settings node. No external calls.
const cfg = $('Settings').first().json;
const MONTHS = 'jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec';
const TRADES = [
  ['Plumbing', /plumb|pipe|water heater|drain|sewer|fixture/i],
  ['HVAC', /hvac|heating|furnace|air condition|ventilation|duct|boiler|heat pump/i],
  ['Electrical', /electric|wiring|panel|lighting|generator|conduit/i],
  ['Roofing', /roof|shingle|gutter/i],
  ['General', /renovat|remodel|build|construction|concrete|framing|drywall|paint/i],
];

function labelled(body, labels) {
  const re = new RegExp('^\\s*(?:' + labels + ')\\s*[:\\-]\\s*(.+)$', 'im');
  const m = body.match(re);
  return m ? m[1].trim() : '';
}

function parseSender(raw) {
  const text = typeof raw === 'string' ? raw : (raw?.text ?? raw?.value?.[0]?.address ?? '');
  const em = text.match(/([^\s<>"',;]+@[^\s<>"',;]+)/);
  const email = em ? em[1].toLowerCase() : '';
  let name = text.replace(/<[^>]*>/, '').replace(/["']/g, '').trim();
  if (!name || name.includes('@')) name = typeof raw === 'object' && raw?.value?.[0]?.name ? raw.value[0].name : '';
  return { name, email };
}

function parseDeadline(text, received) {
  if (!text) return null;
  let t = text.replace(/(\d)(st|nd|rd|th)\b/gi, '$1');
  const hasYear = /\b20\d{2}\b/.test(t) || /\d[\/.]\d{1,2}[\/.]\d{2,4}/.test(t);
  if (!hasYear) t += ', ' + received.getUTCFullYear();
  const d = new Date(t + ' 12:00:00 UTC');
  return isNaN(d) ? null : d;
}

const rows = [];
for (const item of $input.all()) {
  const m = item.json;
  const subject = String(m.subject ?? m.Subject ?? '').trim();
  const body = String(m.text ?? m.textPlain ?? m.snippet ?? '').replace(/\r/g, '');
  const sender = parseSender(m.from ?? m.From ?? '');
  const receivedRaw = m.date ?? m.internalDate ?? null;
  const received = receivedRaw && !isNaN(new Date(receivedRaw)) ? new Date(receivedRaw) : new Date();

  const own = String(cfg.ownEmail || '').toLowerCase();
  const automated = /no-?reply|donotreply|mailer-daemon|newsletter|unsubscribe/i.test(sender.email + ' ' + body.slice(-400));
  const looksLikeRfq = /\b(rfq|request for (?:a )?(?:quote|quotation|proposal|bid)s?|invitation to bid|bid request|quote|estimate|tender|proposal|bid)\b/i.test(subject + ' ' + body);
  const isRfq = looksLikeRfq && !automated && sender.email !== '' && sender.email !== own;

  const phoneLabelled = labelled(body, 'phone|tel|mobile|cell');
  const phoneAny = body.match(/(?:\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}/);
  const phone = phoneLabelled || (phoneAny ? phoneAny[0].trim() : '');

  const location = labelled(body, 'project address|job ?site|site address|address|location|site');

  let deadlineText = labelled(body, 'bids? due|due date|due|deadline|submit by|needed by');
  if (!deadlineText) {
    const dm = body.match(new RegExp('(?:due|by|before|deadline(?: is)?)\\s+(?:on\\s+)?((?:' + MONTHS + ')[a-z]*\\.?\\s+\\d{1,2}(?:st|nd|rd|th)?(?:,?\\s+\\d{4})?|\\d{1,2}[\\/.]\\d{1,2}(?:[\\/.]\\d{2,4})?)', 'i'));
    deadlineText = dm ? dm[1].trim() : '';
  }
  const deadline = parseDeadline(deadlineText, received);

  const budgetLabelled = labelled(body, 'budget');
  const budgetAny = body.match(/\$\s?\d[\d,]*(?:\.\d+)?\s?[kK]?/);
  const budget = budgetLabelled || (budgetAny ? budgetAny[0].trim() : '');

  const hay = subject + ' ' + body;
  const trade = (TRADES.find(([, re]) => re.test(hay)) || ['Other'])[0];

  const scopeLabelled = labelled(body, 'scope|project|description|details');
  const scope = (scopeLabelled || body.replace(/\s+/g, ' ').trim()).slice(0, 280);

  const missing = [];
  if (!phone) missing.push('phone number');
  if (!location) missing.push('project address');
  if (!deadline && !deadlineText) missing.push('bid due date');
  if (scope.length < 40) missing.push('scope of work');

  const daysLeft = deadline ? Math.ceil((deadline - received) / 86400000) : null;
  const priority = daysLeft !== null && daysLeft <= 7 ? 'High' : 'Normal';

  const stamp = received.toISOString().slice(0, 10);
  const idTail = String(m.id ?? '0000').replace(/[^a-z0-9]/gi, '').slice(-4).toUpperCase().padStart(4, '0');

  rows.push({
    json: {
      isRfq,
      rfqId: 'RFQ-' + stamp.replace(/-/g, '') + '-' + idTail,
      received: stamp,
      name: sender.name,
      email: sender.email,
      phone,
      trade,
      location,
      deadline: deadline ? deadline.toISOString().slice(0, 10) : deadlineText,
      budget,
      scope,
      missing: missing.join(', '),
      priority,
      status: 'Reply drafted',
      subject,
      threadId: m.threadId ?? '',
    },
  });
}
return rows;

// Code node "Classify request": adds a request type and a handling level to each parsed row.
// Runs once for all items. No external calls. Rows that are not requests pass through unchanged.
const TYPES = [
  ['Cancellation', /\b(cancel(?:l?ed|lation)?|withdraw(?:n)?|no longer (?:need|require)|project (?:is )?(?:on hold|dead))\b/i],
  ['Addendum', /\b(addendum|addenda|revised (?:drawings?|scope|plans?|bid)|revision|updated (?:drawings?|scope|plans?)|amended)\b/i],
  ['Follow-up', /\b(following up|follow-up|any update|checking in|reminder|still waiting)\b/i],
  ['Bid invitation', /\b(invitation to bid|itb|bid request|bids? due|general contractor|gc\b|bidding)\b/i],
  ['Quote request', /\b(rfq|request for (?:a )?(?:quote|quotation|proposal)s?|quote|estimate|price on|pricing)\b/i],
];
const URGENT = /\b(asap|urgent|emergency|today|tomorrow|rush|immediately)\b/i;

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!r.isRfq) { out.push({ json: { ...r, requestType: 'Not a request', handling: 'Ignore' } }); continue; }
  const text = (r.subject || '') + ' ' + (r.scope || '');
  const requestType = (TYPES.find(([, re]) => re.test(text)) || ['Quote request'])[0];
  const missingCount = r.missing ? r.missing.split(',').length : 0;
  const urgent = r.priority === 'High' || URGENT.test(text);
  // Handling decides what the workflow does next:
  //   Draft reply     a normal request, the reply draft asks for what is missing
  //   Review first    cancellations, addenda and follow-ups: a person decides, no standard reply is written
  //   Call first      urgent and thin on details: a call is faster than an email loop
  let handling = 'Draft reply';
  if (['Cancellation', 'Addendum', 'Follow-up'].includes(requestType)) handling = 'Review first';
  else if (urgent && missingCount >= 2) handling = 'Call first';
  out.push({
    json: {
      ...r,
      requestType,
      handling,
      priority: urgent ? 'High' : r.priority,
      status: handling === 'Draft reply' ? 'Reply drafted' : handling === 'Call first' ? 'Reply drafted, call first' : 'Needs review',
      dedupeKey: (r.threadId || '') !== '' ? 'thread:' + r.threadId
        : 'mail:' + r.email + '|' + String(r.subject || '').toLowerCase().replace(/^((re|fwd?):\s*)+/i, '').replace(/\s+/g, ' ').trim(),
    },
  });
}
return out;

// Code node "Check duplicates": drops requests this workflow has already handled.
// A request is a duplicate when its key (Gmail thread, or sender plus subject) is stored from an
// earlier run, or appears twice in the same batch. Keys are stored by the "Mark as handled" node
// only after the sheet row and the draft succeeded, so a failed run can be retried.
// Static data only persists in an ACTIVE workflow, not in manual test runs.
const store = $getWorkflowStaticData('global');
const handled = store.handledKeys || {};
const seenNow = new Set();
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const dup = Boolean(handled[r.dedupeKey]) || seenNow.has(r.dedupeKey);
  seenNow.add(r.dedupeKey);
  out.push({ json: { ...r, isDuplicate: dup, duplicateNote: dup ? 'Already handled: ' + r.dedupeKey : '' } });
}
return out;

// Code node "Write reply": builds the first reply for each RFQ row.
// The reply confirms receipt, asks for missing details and offers two call times.
// It never states a price or a date for the bid.
const cfg = $('Settings').first().json;
// Call times count from the moment this runs, not from the day the email arrived,
// so a request handled late never gets offered days that have already passed.
// cfg.testNow is only for tests; leave it out of the Settings node.
const now = cfg.testNow ? new Date(cfg.testNow + 'T12:00:00Z') : new Date();

function nextBusinessDays(from, count) {
  const days = [];
  const d = new Date(Date.UTC(from.getUTCFullYear(), from.getUTCMonth(), from.getUTCDate()));
  while (days.length < count) {
    d.setUTCDate(d.getUTCDate() + 1);
    const wd = d.getUTCDay();
    if (wd !== 0 && wd !== 6) days.push(new Date(d));
  }
  return days;
}
const fmt = (d) => d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', timeZone: 'UTC' });

const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (r.handling === 'Review first') {
    // Cancellations, addenda and follow-ups get no standard reply: a person reads them first.
    out.push({ json: { ...r, replySubject: '', replyBody: '' } });
    continue;
  }
  const [d1, d2] = nextBusinessDays(now, 2);
  const lines = [];
  lines.push('We received your request (reference ' + r.rfqId + ') and one of us will review it.');
  if (r.missing) {
    lines.push('');
    lines.push('To prepare an accurate quote we still need: ' + r.missing + '. Reply to this email with those and we will pick it up from there.');
  }
  lines.push('');
  lines.push('If a short call is easier, we can do ' + fmt(d1) + ' at ' + cfg.slotMorning + ' or ' + fmt(d2) + ' at ' + cfg.slotAfternoon + ' (' + cfg.timezoneLabel + '). Tell us which suits you, or suggest another time.');
  if (r.priority === 'High') {
    lines.push('');
    lines.push('We saw the due date in your message and are looking at it first.');
  }
  lines.push('');
  lines.push(cfg.senderName);
  lines.push(cfg.companyName);
  out.push({
    json: {
      ...r,
      replySubject: /^re:/i.test(r.subject) ? r.subject : 'Re: ' + (r.subject || 'Your request'),
      replyBody: lines.join('\n'),
    },
  });
}
return out;

// Code node "Mark as handled": stores the dedupe keys of requests that reached the end without an error.
// Keeps the newest 500 keys. Runs after the Gmail draft was saved.
const store = $getWorkflowStaticData('global');
store.handledKeys = store.handledKeys || {};
const done = $('Write reply').all().map((i) => i.json);
const stamp = new Date().toISOString();
for (const r of done) store.handledKeys[r.dedupeKey] = stamp;
const keys = Object.keys(store.handledKeys).sort((a, b) => store.handledKeys[a].localeCompare(store.handledKeys[b]));
for (const k of keys.slice(0, Math.max(0, keys.length - 500))) delete store.handledKeys[k];
return done.map((r) => ({ json: { rfqId: r.rfqId, dedupeKey: r.dedupeKey, marked: true } }));

// Code node "Describe error": turns a failed sheet write or draft into a plain note for the owner.
// It receives the error output of "Add row to sheet" or "Save reply as draft". Nothing is retried
// and nothing is sent: the note is saved as a Gmail draft so a person sees it.
const cfg = $('Settings').first().json;
const out = [];
for (const item of $input.all()) {
  const e = item.json;
  const src = $('Write reply').all().map((i) => i.json);
  const rfq = src[0] || {};
  const msg = String(e.error?.message ?? e.error ?? e.message ?? 'Unknown error').slice(0, 300);
  out.push({
    json: {
      alertTo: cfg.ownEmail,
      alertSubject: 'Request workflow problem: ' + (rfq.rfqId || 'unknown request'),
      alertBody: [
        'The request workflow could not finish one request.',
        '',
        'Request: ' + (rfq.rfqId || 'unknown') + ' from ' + (rfq.email || 'unknown sender'),
        'Subject: ' + (rfq.subject || ''),
        'Error: ' + msg,
        '',
        'The request was not marked as handled. Check the sheet for a row with this ID, then answer the sender by hand or run the workflow again on the email.',
      ].join('\n'),
    },
  });
}
return out;
